defined('ABSPATH') || exit;
// Update only the exact sentence generated by version 1.0; preserve all other page edits.
add_action('admin_init', function () {
    if (!current_user_can('manage_options') || get_option('bilyan_copy_version') === '1.1') return;
    $page = get_page_by_path('terms');
    if ($page) {
        $old = 'Products marked “' . 'Ask' . ' for a quote” will be quoted by our team.';
        $new = 'For products without a listed price, our team will confirm pricing after submission.';
        if (str_contains($page->post_content, $old)) {
            $result = wp_update_post(wp_slash(['ID' => $page->ID, 'post_content' => str_replace($old, $new, $page->post_content)]), true);
            if (is_wp_error($result)) return;
        }
    }
    update_option('bilyan_copy_version', '1.1', false);
});
add_action('after_switch_theme', function () {
    bilyan_register_types();
    $pages = [
        'cart' => ['Your cart', ''],
        'about' => ['About Bilyan', ''],
        'contact' => ['Contact us', ''],
        'faq' => ['Frequently asked questions', ''],
        'privacy' => ['Privacy policy', '<h2>Your information</h2><p>When you submit an order request, Bilyan collects your name, email, phone number, delivery address, selected products and any notes you provide. We use these details to respond to your request and arrange your order.</p><h2>Storage and sharing</h2><p>Order details are stored on this website and sent to our order notification email address. Our website hosting and email providers process this information to operate these services. We do not collect online payment details.</p><h2>Your browser</h2><p>Your cart is saved in local storage on your device so it remains available when you return. Removing all products clears the cart contents. Standard WordPress cookies may be used for signed-in users.</p><h2>Your choices</h2><p>To ask about your information, request a correction or request deletion of an order record, email hellobilyan@gmail.com. Please do not include sensitive personal information in order notes.</p>'],
        'terms' => ['Ordering & delivery', '<h2>Order requests</h2><p>Submitting your cart sends an order request to Bilyan. It does not collect payment or guarantee stock. Our team will contact you to confirm product availability, final prices and delivery arrangements.</p><h2>Prices and delivery</h2><p>Displayed prices are estimates for the listed products. For products without a listed price, our team will confirm pricing after submission. Delivery charges and any applicable taxes are confirmed before you agree to an order.</p><h2>Changes and returns</h2><p>To change or cancel a request, contact us with your order reference. Ask our team about the return terms for your specific products before confirming your order. Nothing on this page limits applicable consumer rights.</p>'],
    ];
    foreach ($pages as $slug => $page) {
        if (!get_page_by_path($slug)) wp_insert_post(['post_type' => 'page', 'post_status' => 'publish', 'post_name' => $slug, 'post_title' => $page[0], 'post_content' => $page[1]]);
    }
    bilyan_seed_faqs();
    flush_rewrite_rules();
});
add_action('admin_init', function () {
    if (current_user_can('manage_options')) bilyan_seed_faqs();
});
add_action('init', function () {
    if (!get_option('bilyan_faq_seeded')) {
        bilyan_seed_faqs();
        update_option('bilyan_faq_seeded', '1', false);
    }
}, 20);
function bilyan_seed_faqs() {
    if (get_posts(['post_type' => 'bilyan_faq', 'post_status' => 'publish', 'numberposts' => 1])) return;
    $faqs = [
        ['How do I place an order?', 'Browse our products, add your favorites to the cart and choose your quantities. In your cart, fill in your contact details and delivery address, then select “Send order request”. Save the reference shown after submission.'],
        ['Do I need to pay online?', 'No. This website does not collect payments. After receiving your request, our team will contact you to confirm availability, final prices, delivery and any payment arrangements.'],
        ['Can I order a product without a listed price?', 'Some products do not have a listed price. You can still add them to your cart and send your order request. Our team will confirm pricing before you agree to the order.'],
        ['Where do you deliver?', 'We are based in Mogadishu, Somalia. Include your delivery area with your request. Our team will confirm whether delivery is available to your address and any delivery charge before you confirm your order.'],
        ['Can I change or cancel my request?', 'Yes, contact us as soon as possible with your order reference and the changes you need. Our team will confirm what can be arranged.'],
        ['How do I know my request was received?', 'A confirmation screen with a BLY reference appears when your request has been saved. Keep that reference. If you see an error instead, follow the message and try again.'],
        ['Do I need an account?', 'No account is required. Your cart is saved in this browser, and you provide your contact details when sending an order request.'],
    ];
    foreach ($faqs as $order => $faq) wp_insert_post(['post_type' => 'bilyan_faq', 'post_status' => 'publish', 'post_title' => $faq[0], 'post_content' => $faq[1], 'menu_order' => $order]);
}
add_action('admin_menu', function () { add_theme_page('Bilyan setup', 'Bilyan setup', 'manage_options', 'bilyan-setup', 'bilyan_setup_screen'); });
add_action('admin_init', function () {
    register_setting('bilyan', 'bilyan_settings', ['sanitize_callback' => function ($input) {
        return ['email' => sanitize_email($input['email'] ?? ''), 'address' => sanitize_text_field($input['address'] ?? ''), 'currency' => substr(strtoupper(sanitize_text_field($input['currency'] ?? 'USD')), 0, 8)];
    }]);
});
