    <tr><th><label for="bilyan-address">Business address</label></th><td><input class="regular-text" id="bilyan-address" name="bilyan_settings[address]" value="<?php echo esc_attr(bilyan_address()); ?>"></td></tr>
    <tr><th><label for="bilyan-currency">Currency label</label></th><td><input id="bilyan-currency" name="bilyan_settings[currency]" maxlength="8" value="<?php echo esc_attr(bilyan_setting('currency', 'USD')); ?>"><p class="description">Defaults to USD. No conversion is performed. Update product prices when changing currency.</p></td></tr></table>
