    <hr><h2>品牌与静态内容</h2><p>Logo、站点图标：首页、About、联系页、页脚及主题配色可在自定义面板管理。About 完整正文也可切换到页面编辑器。</p><p><a class="button button-primary" href="<?php echo esc_url(admin_url('customize.php')); ?>">打开外观自定义</a></p><h2>Getting started</h2><ol><li>Add categories under <strong>Products → Product categories</strong>.</li><li>Add products with title, excerpt, description and featured image. Price is optional.</li><li>Review requests under <strong>Orders</strong> and update their status.</li><li>Configure an SMTP mail plugin and send a test email before launch.</li><li>Review the Privacy policy and Ordering & delivery pages for your actual business policies.</li></ol>
    <h2>Optional sample catalog</h2><p>Add six clearly labeled demonstration products with bundled illustrations. These are examples, not actual inventory. Remove them or replace their details and images before launch. Importing twice will not duplicate them.</p>
    <form action="<?php echo esc_url(admin_url('admin-post.php')); ?>" method="post"><input type="hidden" name="action" value="bilyan_demo"><?php wp_nonce_field('bilyan_demo'); submit_button('Import sample products', 'secondary'); ?></form></div>
    <?php
}
add_action('admin_post_bilyan_demo', function () {
    if (!current_user_can('manage_options')) wp_die('Not permitted.');
    check_admin_referer('bilyan_demo');
    bilyan_import_demo();
    wp_safe_redirect(admin_url('edit.php?post_type=bilyan_product')); exit;
});
function bilyan_import_demo() {
    $samples = [
        ['Wireless headphones', 'Electronics', 'headphones', '49.00', 'A little more music. A little less noise. Comfortable headphones for everyday listening.'],
        ['Everyday canvas tote', 'Fashion & accessories', 'bag', '18.00', 'Room for the essentials, wherever your day takes you.'],
        ['Modern accent chair', 'Home & living', 'chair', '125.00', 'A comfortable corner starts here. A simple silhouette for your home.'],
        ['Minimal desk lamp', 'Home & living', 'lamp', '32.00', 'A warm finishing touch for your desk or bedside.'],
        ['Classic everyday watch', 'Fashion & accessories', 'watch', '39.00', 'Clean details and timeless style for every day.'],
        ['Reusable water bottle', 'Sports & outdoors', 'bottle', '15.00', 'Your everyday companion for work, walks and everything between.'],
    ];
    foreach ($samples as $index => $sample) {
        $slug = 'sample-' . $sample[2];
        if (get_page_by_path($slug, OBJECT, 'bilyan_product')) continue;
        $term = term_exists($sample[1], 'bilyan_category');
        if (!$term) $term = wp_insert_term($sample[1], 'bilyan_category');
        $id = wp_insert_post(['post_type' => 'bilyan_product', 'post_status' => 'publish', 'post_title' => $sample[0], 'post_name' => $slug, 'post_excerpt' => $sample[4], 'post_content' => '<p>' . $sample[4] . '</p><p><strong>Demonstration product.</strong> This sample shows how a Bilyan product page looks. Replace the description, price and illustration with your actual product information before accepting orders.</p>'], true);
        if (is_wp_error($id)) continue;
        if (!is_wp_error($term)) wp_set_object_terms($id, (int) (is_array($term) ? $term['term_id'] : $term), 'bilyan_category');
        update_post_meta($id, '_bilyan_price', $sample[3]);
        update_post_meta($id, '_bilyan_demo_image', $sample[2]);
        update_post_meta($id, '_bilyan_sku', 'DEMO-00' . ($index + 1));
        update_post_meta($id, '_bilyan_featured', '1');
    }
}
